# Now evaluate consequence for each variant in panel genes
# Note: SOP Rule 5:
# "All variants of the call set that the proband carries count for this, whatever their frequency, genotype quality or own consequence."
# "if one chromosome copy of the proband carries two or more single-nucleotide variants in the same codon, these are assessed together."

# Group variants by (gene, copy, codon_index) for SNVs in CDS
# Let's map each proband variant to genes
for v in proband_variants:
    v['gene_consequences'] = {} # gene -> consequence
    pos = v['pos']
    ref = v['ref']
    alt = v['alt']
    is_snv = (len(ref) == 1 and len(alt) == 1)

    for gname, gd in genes.items():
        gs, ge = gd['span']
        if not (gs <= pos <= ge):
            continue

        # Check splice sites first
        if pos in gd['splice_donors']:
            v['gene_consequences'][gname] = 'splice_donor'
            continue
        if pos in gd['splice_acceptors']:
            v['gene_consequences'][gname] = 'splice_acceptor'
            continue

        # Check CDS
        # Does pos fall in CDS?
        if pos in gd['coord_to_cds']:
            if not is_snv:
                # indel
                diff = len(alt) - len(ref)
                if diff % 3 != 0:
                    v['gene_consequences'][gname] = 'frameshift'
                else:
                    v['gene_consequences'][gname] = 'inframe_indel'
            else:
                # SNV in CDS
                # we will process codons below
                pass
        else:
            # Outside CDS and not splice site: could be UTR, intron, etc.
            # Not qualifying
            pass

# Now handle SNVs in CDS per gene
for gname, gd in genes.items():
    strand = gd['strand']
    cds_seq = list(gd['cds_seq'])
    coord_to_cds = gd['coord_to_cds']

    # find all SNVs in CDS for this gene carried by proband
    snvs = [v for v in proband_variants if v['pos'] in coord_to_cds and len(v['ref']) == 1 and len(v['alt']) == 1]

    # Group by codon index
    # codon index = cds_pos // 3
    # Each variant has copy: 'maternal', 'paternal', 'both', 'unassigned'
    # SOP: "if one chromosome copy of the proband carries two or more single-nucleotide variants in the same codon, these are assessed together."
    # Copies to evaluate: maternal copy, paternal copy.
    # A variant on 'both' is on maternal and paternal.
    # A variant on 'maternal' is on maternal.
    # A variant on 'paternal' is on paternal.
    # A variant on 'unassigned' is assessed together only with variants on 'both'.

    # Let's inspect which codons have SNVs
    codon_snvs = {}
    for v in snvs:
        cds_p = coord_to_cds[v['pos']]
        c_idx = cds_p // 3
        codon_snvs.setdefault(c_idx, []).append((cds_p % 3, v))

    for c_idx, var_list in codon_snvs.items():
        ref_codon = ''.join(cds_seq[c_idx*3 : c_idx*3 + 3])
        ref_aa = CODON_TABLE.get(ref_codon, '?')

        # Evaluate each variant on its copy/copies
        for c_offset, v in var_list:
            # What copies does v lie on?
            copies_to_test = []
            if v['copy'] == 'both':
                copies_to_test = ['maternal', 'paternal']
            elif v['copy'] == 'maternal':
                copies_to_test = ['maternal']
            elif v['copy'] == 'paternal':
                copies_to_test = ['paternal']
            else:
                copies_to_test = ['unassigned']

            conseq_per_copy = []
            for cpy in copies_to_test:
                # find all SNVs in this codon on this copy
                codon_bases = list(ref_codon)
                for co, ov in var_list:
                    # is ov on cpy?
                    on_cpy = False
                    if cpy == 'maternal' and ov['copy'] in ('maternal', 'both'):
                        on_cpy = True
                    elif cpy == 'paternal' and ov['copy'] in ('paternal', 'both'):
                        on_cpy = True
                    elif cpy == 'unassigned' and (ov is v or ov['copy'] == 'both'):
                        on_cpy = True
                    if on_cpy:
                        # base in transcript
                        b = ov['alt'] if strand == '+' else revcomp(ov['alt'])
                        codon_bases[co] = b
                mut_codon = ''.join(codon_bases)
                mut_aa = CODON_TABLE.get(mut_codon, '?')

                if mut_aa == '*':
                    cq = 'stop_gained'
                elif mut_aa != ref_aa:
                    cq = 'missense'
                else:
                    cq = 'synonymous'
                conseq_per_copy.append(cq)

            if v['copy'] == 'both':
                # Rule 5: "A variant of which the proband carries two copies qualifies only if its consequence qualifies on both copies (if the two classes differ, report both joined by '&')."
                q_classes = {'missense', 'stop_gained', 'frameshift', 'splice_acceptor', 'splice_donor'}
                if conseq_per_copy[0] in q_classes and conseq_per_copy[1] in q_classes:
                    if conseq_per_copy[0] == conseq_per_copy[1]:
                        v['gene_consequences'][gname] = conseq_per_copy[0]
                    else:
                        v['gene_consequences'][gname] = f'{conseq_per_copy[0]}&{conseq_per_copy[1]}'
                else:
                    v['gene_consequences'][gname] = 'non_qualifying'
            else:
                v['gene_consequences'][gname] = conseq_per_copy[0]

print('\n=== CANDIDATE REVIEW ===')
qualifying_classes = {'missense', 'stop_gained', 'frameshift', 'splice_acceptor', 'splice_donor'}

# Filter candidates that pass rules 2-6
# Rule 2: usable genotypes
# Rule 3: allele balance
# Rule 4: AF < 0.001
# Rule 5: qualifying consequence
# Rule 6: gene in panel

passed_variants = []
for v in proband_variants:
    if not v['usable']:
        continue
    if not v['ab_pass']:
        continue
    if v['af'] >= 0.001:
        continue
    for gname, cq in v['gene_consequences'].items():
        # check if cq qualifies (can be class or class1&class2)
        parts = cq.split('&')
        if all(p in qualifying_classes for p in parts):
            passed_variants.append((v, gname, cq))

print(f'Total passed variants with qualifying consequence in panel genes: {len(passed_variants)}')
for v, gname, cq in passed_variants:
    print(f'{v["chrom"]}:{v["pos"]} {v["ref"]}>{v["alt"]} gene={gname} cq={cq} p={v["p_copies"]} f={v["f_copies"]} m={v["m_copies"]}')
EOF
python3 /task/work/test_candidates_full.py

