# Check all codons for proband variants
from test_candidates_full import proband_variants, genes

for gname, gd in genes.items():
    coord_to_cds = gd['coord_to_cds']
    snvs = [v for v in proband_variants if v['pos'] in coord_to_cds and len(v['ref']) == 1 and len(v['alt']) == 1]
    codon_groups = {}
    for v in snvs:
        cp = coord_to_cds[v['pos']]
        c_idx = cp // 3
        codon_groups.setdefault(c_idx, []).append((cp % 3, v))
    for c_idx, vars_in_c in codon_groups.items():
        if len(vars_in_c) > 1:
            print(f'Gene {gname} codon {c_idx} has {len(vars_in_c)} SNVs:')
            for fr, v in vars_in_c:
                print(f'   pos={v["pos"]} {v["ref"]}>{v["alt"]} copy={v["copy"]} p={v["p_copies"]} f={v["f_copies"]} m={v["m_copies"]}')
EOF
